[
  {
    "name": "陈望",
    "description": "35岁，在大城市工作的儿子，多年未归，与父亲有未解的心结，本片情感核心主角",
    "appearance": "中等身高偏瘦，黑色短发略有凌乱，眼下有淡淡黑眼圈，下颌线条分明，眉眼间有疲惫",
    "costume": "深灰色羊毛大衣，内搭黑色高领毛衣，深色长裤，背一只旧皮双肩包",
    "personality": "表面沉默寡言，内心柔软敏感，习惯用距离保护自己"
  },
  {
    "name": "陈父",
    "description": "62岁，陈望的父亲，退休工人，传统严厉，不善表达爱",
    "appearance": "花白短发，瘦削脸颊有深刻法令纹，眉头常紧锁，背微驼",
    "costume": "深蓝色对襟棉袄外套，灰色毛背心，深色棉裤",
    "personality": "沉默固执，话少但句句带刺，深爱儿子却不知如何开口"
  },
  {
    "name": "陈母",
    "description": "58岁，陈望的母亲，家庭主妇，全家的情感润滑剂",
    "appearance": "齐耳短发有少许白发，圆润温和的脸，总是带着微笑，眼角有笑纹",
    "costume": "暗红色碎花棉袄，黑色棉裤，围一条米白色围裙",
    "personality": "温柔坚韧，嘴碎心软，是家庭关系的缝合者"
  },
  {
    "name": "爷爷",
    "description": "85岁，陈望的爷爷，坐在堂屋正中，是家族精神的象征",
    "appearance": "满头银发稀疏，深深的皱纹，浑浊但温和的眼睛，缺了一颗门牙",
    "costume": "深棕色对襟盘扣棉袄，戴一顶黑色绒线帽",
    "personality": "豁达通透，少言寡语，一开口便是人生智慧"
  }
]

[
  {
    "name": "北方小镇黄昏街道",
    "description": "陈望归乡下车的小镇主街，挂满红灯笼与春联，年味浓郁",
    "visualStyle": "黄昏暖橙色天光，地面薄雪反射灯笼红光，远处有零星烟火，16:9横构图街道延伸感"
  },
  {
    "name": "老宅院门",
    "description": "陈家老宅的木门，贴着褪色的春联，门头挂一盏红灯笼",
    "visualStyle": "夜色中灯笼发出温暖红光，木门斑驳质感，门缝透出屋内暖黄灯光"
  },
  {
    "name": "堂屋",
    "description": "老宅正厅，八仙桌居中，挂着中堂画，是年夜饭与家族仪式的空间",
    "visualStyle": "暖黄色白炽灯，红纸窗花，老式条凳，墙上老照片，氤氲热气感"
  },
  {
    "name": "厨房",
    "description": "狭小但充满烟火气的灶台，母亲忙碌的身影与升腾的蒸汽",
    "visualStyle": "灶火暖橙光从下往上打亮母亲的脸，蒸汽朦胧柔焦，墙上挂满腊肉蒜头"
  },
  {
    "name": "陈望老屋卧室",
    "description": "陈望从小住到大的小屋，墙上贴着泛黄的老奖状，木质书桌",
    "visualStyle": "台灯昏黄暖光，窗外透进清冷月色，怀旧静谧的时光凝固感"
  },
  {
    "name": "老宅院子",
    "description": "四合院中间的小院，挂着腌货，堆着鞭炮纸箱",
    "visualStyle": "夜空墨蓝，远处烟花绽放映照积雪，灯笼红光点染画面"
  }
]
